  f6n: "Composición de texto real para árabe, hindi, tailandés, chino, japonés y coreano, elegidos desde un selector con banderas.",
  screensTitle: "Ajustes sin editar archivos",
  screensSub: "Pulsa el engranaje (o F2) en el menú, o abre la app de escritorio. Ambos editan los mismos ajustes.",
  capSettings: "En el menú de arranque: tema, fondo, temporizador de inicio automático, entrada predeterminada (también «la última elegida») y cada entrada con mostrar/ocultar, renombrar y reordenar.",
  capLangs: "El selector de idioma (tecla L): 34 idiomas con sus banderas y nombres nativos.",
  installTitle: "Instalar",
  installSub: "bootpick se instala desde Linux. Se copia a la partición EFI, añade una entrada de arranque al firmware y la pone primero. GRUB, systemd-boot y el gestor de arranque de Windows no se tocan, así que el menú de arranque del firmware (a menudo <code>F12</code>) puede seguir iniciándolos directamente.",
  betaNote: "<strong>Beta.</strong> Probado hasta ahora en una sola computadora real (ver <a href=\"tested/\">Probado en</a>) y en QEMU. Pruébalo primero desde una memoria USB y averigua cómo abrir el menú de arranque de tu firmware.",
  dlTitle: "Instalación rápida: descarga",
  dlSub: "Sin Rust: descarga el paquete ya compilado de la <a href=\"https://github.com/Devace-93/bootpick/releases\">página de versiones</a>, descomprímelo y ejecuta el instalador. Funciona en Ubuntu 24.04, Pop!_OS 24.04, Debian 13 o más recientes. Para compilarlo tú mismo, sigue los pasos 1 a 3.",
  buildTitle: "1 · Compilar",
