  installStepSub: "También instala la app <strong>bootpick settings</strong> y la abre. Ejecútalo de nuevo para actualizar: si bootpick ya está en la computadora (aunque se haya instalado desde otro Linux), actualiza esa copia y pregunta si <strong>conservar</strong> tus ajustes o <strong>restablecerlos</strong>.",
  reqTitle: "Requisitos",
  req1: "Una computadora UEFI de 64 bits (la mayoría de los PC desde 2012). El modo BIOS heredado no es compatible.",
