  req3: "Un Linux desde el cual instalar. Las computadoras solo con Windows aún no son compatibles.",
  req4: "Para usar el mouse en el menú, el firmware necesita un controlador de puntero (la mayoría de las laptops lo tienen). Sin él, el teclado lo hace todo.",
