  rm2: "<strong>Desinstalar</strong> en la app: quita el menú, su entrada de arranque y la app, y vuelve a mostrar los menús que ocultó. Desde una terminal: <code>sudo ./install.sh --uninstall</code>.",
  rm3: "¿Atascado? Elige tu gestor anterior desde el menú de arranque del firmware (<code>F12</code>, <code>F9</code> o <code>Esc</code> en la mayoría de los equipos).",
  appTitle: "La app de ajustes",
  appSub: "Abre <strong>bootpick settings</strong> desde el menú de aplicaciones. Pide tu contraseña una vez y muestra una vista previa en vivo dibujada por el mismo código que el menú de arranque.",
  whatTitle: "Qué puedes cambiar",
