  menusTitle: "Los menús después de bootpick",
  menusSub: "Ubuntu y su familia arrancan con GRUB, Pop!_OS con systemd-boot, y ambos pueden mostrar su propio menú después de bootpick. La app los lista y oculta cada uno con un clic (un bloque marcado en <code>custom.cfg</code> de GRUB, <code>timeout 0</code> en <code>loader.conf</code>), y los restaura con la misma facilidad.",
  menusNote: "Para cada GRUB, <em>Ocultarlo también tras un apagado forzado</em> decide si el menú sigue apareciendo cuando el arranque anterior no terminó, para que la recuperación quede a una tecla de distancia.",
  howTitle: "Cómo funciona",
