  menusSub: "Ubuntu und Verwandte starten über GRUB, Pop!_OS über systemd-boot, und beide können nach bootpick ihr eigenes Menü zeigen. Die App listet sie auf und blendet jedes mit einem Klick aus (ein markierter Block in GRUBs <code>custom.cfg</code>, <code>timeout 0</code> in <code>loader.conf</code>) – und genauso leicht wieder ein.",
  menusNote: "Pro GRUB entscheidet <em>Auch nach einem erzwungenen Herunterfahren ausblenden</em>, ob das Menü noch erscheint, wenn der vorige Start nicht abgeschlossen wurde – so bleibt die Wiederherstellung nur eine Taste entfernt.",
