  heroLede: "O bootpick substitui o menu de texto do GRUB e do systemd-boot por ícones grandes, um papel de parede e o mouse. Ele encontra sozinho o Windows e cada Linux em todos os seus discos, inicia o que você escolher e permite renomear, ocultar e reordenar os sistemas pelo menu ou por um app de desktop. Seus carregadores de boot atuais continuam onde estão.",
