  capLangs: "O seletor de idioma (tecla L): 34 idiomas com suas bandeiras e nomes nativos.",
  installTitle: "Instalar",
  installSub: "O bootpick é instalado a partir do Linux. Ele se copia para a partição EFI, adiciona uma entrada de boot no firmware e a coloca em primeiro lugar. GRUB, systemd-boot e o gerenciador de boot do Windows não são alterados, então o menu de boot do firmware (geralmente <code>F12</code>) ainda pode iniciá-los diretamente.",
  betaNote: "<strong>Beta.</strong> Testado até agora em um único computador real (veja <a href=\"tested/\">Testado em</a>) e no QEMU. Experimente primeiro a partir de um pendrive e saiba como abrir o menu de boot do seu firmware.",
  dlTitle: "Instalação rápida: download",
  dlSub: "Sem Rust: baixe o pacote pronto na <a href=\"https://github.com/Devace-93/bootpick/releases\">página de versões</a>, descompacte e execute o instalador. Funciona no Ubuntu 24.04, Pop!_OS 24.04, Debian 13 ou mais recentes. Para compilar você mesmo, siga os passos 1 a 3.",
  buildTitle: "1 · Compilar",
  buildSub: "Requer uma toolchain Rust (<a href=\"https://rustup.rs\">rustup</a>) e <a href=\"https://docs.astral.sh/uv/\">uv</a>, além do cairo e das fontes Noto para os ícones e as escritas não latinas. No Debian, Ubuntu ou Pop!_OS:",
  usbTitle: "2 · Experimente a partir de um pendrive (opcional)",
  usbSub: "Copia o menu para um pendrive FAT32. Inicie o pendrive pelo menu de boot do firmware: nada muda no disco.",
  installStepTitle: "3 · Instalar",
  installStepSub: "Também instala o app <strong>bootpick settings</strong> e o abre. Execute de novo para atualizar: se o bootpick já estiver no computador (mesmo instalado a partir de outro Linux), ele atualiza essa cópia e pergunta se deve <strong>manter</strong> suas configurações ou <strong>redefini-las</strong>.",
  reqTitle: "Requisitos",
  req1: "Um computador UEFI de 64 bits (a maioria dos PCs desde 2012). O modo BIOS legado não é suportado.",
  req2: "<strong>Secure Boot desativado</strong>, ou o binário assinado com a sua própria chave.",
  req3: "Um Linux para fazer a instalação. Computadores só com Windows ainda não são suportados.",
  req4: "Usar o mouse no menu requer um firmware com driver de ponteiro (a maioria dos notebooks tem). Sem ele, o teclado faz tudo.",
  removeTitle: "Desativar ou remover",
  rm1: "<strong>Desativar</strong> no app: o próximo carregador na ordem de boot é iniciado, nada é apagado.",
  rm2: "<strong>Desinstalar</strong> no app: remove o menu, sua entrada de boot e o app, e volta a mostrar os menus que ele ocultou. Pelo terminal: <code>sudo ./install.sh --uninstall</code>.",
  rm3: "Travou? Escolha seu carregador antigo no menu de boot do firmware (<code>F12</code>, <code>F9</code> ou <code>Esc</code> na maioria das máquinas).",
  appTitle: "O app de configurações",
  appSub: "Abra o <strong>bootpick settings</strong> pelo menu de aplicativos. Ele pede sua senha uma vez e mostra uma prévia ao vivo desenhada pelo mesmo código do menu de inicialização.",
