  w1: "Idioma, temporizador de início automático e entrada padrão.",
  w2: "Nomes e logos: importe qualquer imagem como logo de um sistema.",
  w3: "Papéis de parede: adicione suas próprias imagens ou remova as incluídas.",
  w4: "Temas: duplique um tema embutido e mude cada cor.",
  w5: "Desfazer e refazer em cada alteração, e uma confirmação antes de perder alterações não salvas.",
  menusTitle: "Os menus depois do bootpick",
  menusSub: "O Ubuntu e sua família iniciam pelo GRUB, o Pop!_OS pelo systemd-boot, e ambos podem mostrar o próprio menu depois do bootpick. O app os lista e oculta cada um com um clique (um bloco marcado no <code>custom.cfg</code> do GRUB, <code>timeout 0</code> no <code>loader.conf</code>), e os restaura com a mesma facilidade.",
  menusNote: "Para cada GRUB, <em>Ocultar também após um desligamento forçado</em> decide se o menu ainda aparece quando a inicialização anterior não terminou, para que a recuperação fique a uma tecla de distância.",
  howTitle: "Como funciona",
  howSub: "O bootpick é um pequeno aplicativo UEFI escrito em Rust sem a biblioteca padrão. O firmware o inicia como qualquer outro carregador de boot.",
