  w5: "Ongedaan maken en opnieuw voor elke wijziging, en een bevestiging voordat niet-opgeslagen werk verloren gaat.",
  menusTitle: "De menu's na bootpick",
  menusSub: "Ubuntu en verwanten starten via GRUB, Pop!_OS via systemd-boot, en beide kunnen na bootpick hun eigen menu tonen. De app toont ze en verbergt elk met één klik (een gemarkeerd blok in GRUB's <code>custom.cfg</code>, <code>timeout 0</code> in <code>loader.conf</code>), en zet ze net zo makkelijk terug.",
  menusNote: "Per GRUB bepaalt <em>Ook verbergen na een geforceerde uitschakeling</em> of het menu nog verschijnt als de vorige start niet is voltooid, zodat herstel één toets verwijderd blijft.",
  howTitle: "Hoe het werkt",
  howSub: "bootpick is een kleine UEFI-applicatie, geschreven in Rust zonder de standaardbibliotheek. De firmware start het zoals elke andere bootloader.",
  h1r: "Scannen",
  h1n: "Leest elke EFI-partitie en de opstartopties van de firmware en deelt wat het vindt in in systemen en extra's.",
  h2r: "Tekenen",
