  h3r: "Starten",
  h3n: "Laadt de gekozen loader direct. systemd-boot krijgt het item via <code>LoaderEntryOneShot</code>; firmwareopties via <code>BootNext</code>.",
  h4r: "Onthouden",
  h4n: "Instellingen staan in <code>\\EFI\\bootpick\\bootpick.conf</code>, een gewoon tekstbestand dat elke geïnstalleerde Linux kan bewerken.",
