  s2: "\"Security violation\" of er gebeurt niets",
  c2: "Secure Boot staat aan. Schakel het uit in de firmware-instellingen.",
  s3: "Geen muisaanwijzer",
  c3: "De firmware biedt geen aanwijsapparaat aan. Gebruik het toetsenbord, of zet een UEFI-muisstuurprogramma in <code>\\EFI\\bootpick\\drivers\\</code>.",
  s4: "Er ontbreekt een systeem",
  c4: "Druk op Esc om verborgen items te tonen en vink het daarna aan in de instellingen. Versleutelde of LVM-schijven zijn geen probleem: bootpick heeft alleen hun loader op een EFI-partitie nodig.",
  s5: "GRUB toont nog steeds zijn menu",
  c5: "Verberg het in de app. Verschijnt het alleen na een start die niet is voltooid, dan is dat het herstelgedrag van GRUB; vink \"Ook verbergen na een geforceerde uitschakeling\" aan om het ook dan te verbergen.",
  s6: "Het blijft hangen na het kiezen van een systeem",
  c6: "Kijk in <code>\\EFI\\bootpick\\bootpick.log</code>: daar staat of bootpick de controle aan de loader heeft overgedragen. Sommige firmware blijft hangen met bepaalde USB-sticks erin, met of zonder bootpick.",
