  source: "Broncode",
  disclaimer: "bootpick is een onafhankelijk opensourceproject, niet verbonden aan of goedgekeurd door Microsoft, Canonical, System76, elementary of enig ander bedrijf waarvan het het systeem start. Productnamen en logo's zijn eigendom van hun eigenaars en worden alleen gebruikt om die systemen aan te duiden.",
  altMenu: "Hoofdscherm van bootpick: Ubuntu, Windows, Pop!_OS en een tweede Ubuntu als grote pictogrammen op een nevelachtergrond",
