  dlSub: "Ingen Rust behövs: ladda ner det färdiga paketet från <a href=\"https://github.com/Devace-93/bootpick/releases\">versionssidan</a>, packa upp det och kör installationsskriptet. Fungerar på Ubuntu 24.04, Pop!_OS 24.04, Debian 13 eller nyare. Vill du bygga själv, följ steg 1 till 3.",
