  betaNote: "<strong>Beta.</strong> Jak dotąd przetestowano na jednym prawdziwym komputerze (zobacz <a href=\"tested/\">Testowano na</a>) i w QEMU. Najpierw wypróbuj z pendrive'a i upewnij się, że wiesz, jak otworzyć menu rozruchu swojego firmware.",
