  installSub: "Το bootpick εγκαθίσταται από Linux. Αντιγράφεται στο διαμέρισμα EFI, προσθέτει μια καταχώριση εκκίνησης στο firmware και τη βάζει πρώτη. Τα GRUB, systemd-boot και ο διαχειριστής εκκίνησης των Windows δεν αγγίζονται, οπότε το μενού εκκίνησης του firmware (συχνά <code>F12</code>) μπορεί ακόμη να τα εκκινεί απευθείας.",
  betaNote: "<strong>Beta.</strong> Έχει δοκιμαστεί μέχρι στιγμής σε έναν πραγματικό υπολογιστή (δείτε <a href=\"tested/\">Δοκιμασμένο σε</a>) και στο QEMU. Δοκιμάστε το πρώτα από ένα USB stick και μάθετε πώς ανοίγει το μενού εκκίνησης του firmware σας.",
  dlTitle: "Γρήγορη εγκατάσταση: λήψη",
  dlSub: "Χωρίς Rust: κατεβάστε το έτοιμο πακέτο από τη <a href=\"https://github.com/Devace-93/bootpick/releases\">σελίδα εκδόσεων</a>, αποσυμπιέστε το και τρέξτε το πρόγραμμα εγκατάστασης. Λειτουργεί σε Ubuntu 24.04, Pop!_OS 24.04, Debian 13 ή νεότερα. Για μεταγλώττιση από εσάς, ακολουθήστε τα βήματα 1 έως 3.",
  buildTitle: "1 · Μεταγλώττιση",
  buildSub: "Χρειάζεται εργαλεία Rust (<a href=\"https://rustup.rs\">rustup</a>) και <a href=\"https://docs.astral.sh/uv/\">uv</a>, καθώς και cairo και τις γραμματοσειρές Noto για τα εικονίδια και τις μη λατινικές γραφές. Σε Debian, Ubuntu ή Pop!_OS:",
  usbTitle: "2 · Δοκιμάστε το από USB stick (προαιρετικό)",
  usbSub: "Αντιγράφει το μενού σε ένα stick FAT32. Εκκινήστε το stick από το μενού εκκίνησης του firmware: τίποτα στον δίσκο δεν αλλάζει.",
  installStepTitle: "3 · Εγκατάσταση",
  installStepSub: "Εγκαθιστά επίσης την εφαρμογή <strong>Ρυθμίσεις bootpick</strong> και την ανοίγει. Εκτελέστε το ξανά για ενημέρωση: αν το bootpick υπάρχει ήδη στον υπολογιστή (ακόμη κι αν εγκαταστάθηκε από άλλο Linux), ενημερώνει εκείνο το αντίγραφο και ρωτά αν θα <strong>κρατήσετε</strong> τις ρυθμίσεις σας ή θα τις <strong>επαναφέρετε</strong>.",
  reqTitle: "Απαιτήσεις",
  req1: "Υπολογιστής UEFI 64 bit (οι περισσότεροι PC από το 2012). Η λειτουργία Legacy BIOS δεν υποστηρίζεται.",
  req2: "<strong>Secure Boot απενεργοποιημένο</strong>, ή το εκτελέσιμο υπογεγραμμένο με δικό σας κλειδί.",
  req3: "Linux για την εγκατάσταση. Υπολογιστές μόνο με Windows δεν υποστηρίζονται ακόμη.",
  req4: "Το ποντίκι στο μενού χρειάζεται firmware με οδηγό δείκτη (τον έχουν οι περισσότεροι φορητοί). Χωρίς αυτόν, το πληκτρολόγιο κάνει τα πάντα.",
  removeTitle: "Απενεργοποίηση ή αφαίρεση",
  rm1: "<strong>Απενεργοποίηση</strong> στην εφαρμογή: εκκινεί ο επόμενος φορτωτής στη σειρά εκκίνησης, τίποτα δεν διαγράφεται.",
  rm2: "<strong>Απεγκατάσταση</strong> στην εφαρμογή: αφαιρεί το μενού, την καταχώριση εκκίνησής του και την εφαρμογή, και εμφανίζει ξανά τα μενού που είχε κρύψει. Από τερματικό: <code>sudo ./install.sh --uninstall</code>.",
  rm3: "Κολλήσατε; Επιλέξτε τον παλιό φορτωτή σας από το μενού εκκίνησης του firmware (<code>F12</code>, <code>F9</code> ή <code>Esc</code> στους περισσότερους υπολογιστές).",
  appTitle: "Η εφαρμογή ρυθμίσεων",
  appSub: "Ανοίξτε τις <strong>Ρυθμίσεις bootpick</strong> από το μενού εφαρμογών. Ζητά τον κωδικό σας μία φορά και δείχνει ζωντανή προεπισκόπηση, σχεδιασμένη από τον ίδιο κώδικα με το μενού εκκίνησης.",
  whatTitle: "Τι μπορείτε να αλλάξετε",
