  w5: "Αναίρεση και επανάληψη για κάθε αλλαγή, επιβεβαίωση πριν χαθεί μη αποθηκευμένη εργασία.",
  menusTitle: "Τα μενού μετά το bootpick",
  menusSub: "Το Ubuntu και η οικογένειά του ξεκινούν μέσω GRUB, το Pop!_OS μέσω systemd-boot, και τα δύο μπορούν να δείξουν δικό τους μενού μετά το bootpick. Η εφαρμογή τα εμφανίζει και κρύβει το καθένα με ένα κλικ (ένα σημαδεμένο μπλοκ στο <code>custom.cfg</code> του GRUB, <code>timeout 0</code> στο <code>loader.conf</code>), και τα επαναφέρει εξίσου εύκολα.",
  menusNote: "Για κάθε GRUB, η επιλογή <em>Απόκρυψη και μετά από αναγκαστικό τερματισμό</em> καθορίζει αν το μενού εμφανίζεται ακόμη όταν η προηγούμενη εκκίνηση δεν ολοκληρώθηκε, ώστε η ανάκτηση να απέχει ένα πλήκτρο.",
