  installTitle: "इंस्टॉल",
  installSub: "bootpick को Linux से इंस्टॉल किया जाता है। यह खुद को EFI पार्टिशन में कॉपी करता है, फ़र्मवेयर में एक बूट एंट्री जोड़ता है और उसे सबसे पहले रखता है। GRUB, systemd-boot और Windows बूट मैनेजर को छुआ नहीं जाता, इसलिए फ़र्मवेयर का बूट मेन्यू (अक्सर <code>F12</code>) उन्हें अब भी सीधे शुरू कर सकता है।",
  betaNote: "<strong>बीटा।</strong> अब तक एक असली कंप्यूटर (देखें <a href=\"tested/\">इन पर परखा</a>) और QEMU में परखा गया है। पहले USB स्टिक से आज़माएँ और जान लें कि अपने फ़र्मवेयर का बूट मेन्यू कैसे खोलते हैं।",
  dlTitle: "त्वरित इंस्टॉल: डाउनलोड",
  dlSub: "Rust की ज़रूरत नहीं: <a href=\"https://github.com/Devace-93/bootpick/releases\">रिलीज़ पेज</a> से तैयार पैकेज डाउनलोड करें, उसे अनपैक करें और इंस्टॉलर चलाएँ। Ubuntu 24.04, Pop!_OS 24.04, Debian 13 या नए पर चलता है। खुद बिल्ड करने के लिए चरण 1 से 3 अपनाएँ।",
  buildTitle: "1 · बिल्ड",
