  installStepTitle: "3 · इंस्टॉल",
  installStepSub: "यह <strong>bootpick सेटिंग्स</strong> ऐप भी इंस्टॉल करता है और उसे खोलता है। अपडेट करने के लिए इसे फिर चलाएँ: अगर bootpick पहले से कंप्यूटर पर है (किसी दूसरे Linux से इंस्टॉल हो तब भी), तो यह उसी कॉपी को अपडेट करता है और पूछता है कि आपकी सेटिंग्स <strong>रखनी</strong> हैं या <strong>रीसेट</strong> करनी हैं।",
  reqTitle: "आवश्यकताएँ",
