  req2: "<strong>Secure Boot बंद</strong>, या बाइनरी आपकी अपनी कुंजी से साइन की हुई।",
  req3: "इंस्टॉल करने के लिए Linux। सिर्फ़ Windows वाले कंप्यूटर अभी समर्थित नहीं हैं।",
  req4: "मेन्यू में माउस के लिए पॉइंटर ड्राइवर वाला फ़र्मवेयर चाहिए (ज़्यादातर लैपटॉप में होता है)। उसके बिना कीबोर्ड से सब कुछ होता है।",
  removeTitle: "बंद करें या हटाएँ",
