  rm2: "ऐप में <strong>अनइंस्टॉल</strong>: मेन्यू, उसकी बूट एंट्री और ऐप को हटाता है, और छिपाए गए मेन्यू फिर से दिखाता है। टर्मिनल से: <code>sudo ./install.sh --uninstall</code>।",
