  menusTitle: "bootpick के बाद के मेन्यू",
  menusSub: "Ubuntu और उसका परिवार GRUB से शुरू होते हैं, Pop!_OS systemd-boot से, और दोनों bootpick के बाद अपना मेन्यू दिखा सकते हैं। ऐप उनकी सूची दिखाता है और हर एक को एक क्लिक में छिपाता है (GRUB की <code>custom.cfg</code> में एक चिह्नित ब्लॉक, <code>loader.conf</code> में <code>timeout 0</code>), और उतनी ही आसानी से वापस लाता है।",
